package com.example.desktop;

import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.control.*;
import javafx.scene.layout.*;

import java.util.*;

/** Combined CEC-oriented raceway fill and conductor derating worksheet. */
public final class RacewayAmpacityPane extends BorderPane {
    private static final String INPUT="-fx-background-color:white;-fx-border-color:#cbd5e1;-fx-border-radius:8;-fx-background-radius:8;-fx-padding:8 9;";
    private static final String PRIMARY="-fx-background-color:#0e7490;-fx-text-fill:white;-fx-font-weight:bold;-fx-background-radius:8;-fx-padding:9 13;";
    private static final String SECONDARY="-fx-background-color:#f8fafc;-fx-text-fill:#0f4c81;-fx-border-color:#c7d9e8;-fx-border-radius:8;-fx-background-radius:8;-fx-padding:8 11;-fx-font-weight:bold;";
    private static final String CARD="-fx-background-color:white;-fx-background-radius:14;-fx-border-color:#dfe7ef;-fx-border-radius:14;-fx-padding:16;";

    private record Preset(double area,double a60,double a75,double a90){}
    private static final LinkedHashMap<String,Preset> CU=new LinkedHashMap<>();
    private static final LinkedHashMap<String,LinkedHashMap<String,Double>> RACEWAY=new LinkedHashMap<>();
    static {
        p("14 AWG",8.87,15,20,25);p("12 AWG",11.60,20,25,30);p("10 AWG",15.70,30,35,40);p("8 AWG",28.20,40,50,55);p("6 AWG",38,55,65,75);p("4 AWG",52.5,70,85,95);p("3 AWG",62,85,100,115);p("2 AWG",73.9,95,115,130);p("1 AWG",99.1,110,130,145);p("1/0 AWG",119,125,150,170);p("2/0 AWG",142,145,175,195);p("3/0 AWG",171,165,200,225);p("4/0 AWG",207,195,230,260);p("250 kcmil",252,215,255,290);p("300 kcmil",293,240,285,320);p("350 kcmil",332,260,310,350);p("400 kcmil",373,280,335,380);p("500 kcmil",460,320,380,430);p("600 kcmil",540,350,420,475);p("750 kcmil",650,400,475,535);p("1000 kcmil",840,455,545,615);
        LinkedHashMap<String,Double> emt=new LinkedHashMap<>();r(emt,"16 (1/2 in)",186);r(emt,"21 (3/4 in)",330);r(emt,"27 (1 in)",539);r(emt,"35 (1-1/4 in)",940);r(emt,"41 (1-1/2 in)",1288);r(emt,"53 (2 in)",2132);r(emt,"63 (2-1/2 in)",3783);r(emt,"78 (3 in)",5701);r(emt,"91 (3-1/2 in)",7451);r(emt,"103 (4 in)",9503);RACEWAY.put("EMT",emt);
        LinkedHashMap<String,Double> pvc=new LinkedHashMap<>();r(pvc,"16 (1/2 in)",167);r(pvc,"21 (3/4 in)",307);r(pvc,"27 (1 in)",507);r(pvc,"35 (1-1/4 in)",792);r(pvc,"41 (1-1/2 in)",1140);r(pvc,"53 (2 in)",2027);r(pvc,"63 (2-1/2 in)",2951);r(pvc,"78 (3 in)",4560);r(pvc,"91 (3-1/2 in)",6138);r(pvc,"103 (4 in)",7870);r(pvc,"129 (5 in)",12439);r(pvc,"155 (6 in)",17613);RACEWAY.put("Rigid PVC",pvc);
    }
    private static void p(String s,double area,double a60,double a75,double a90){CU.put(s,new Preset(area,a60,a75,a90));}
    private static void r(Map<String,Double> m,String s,double a){m.put(s,a);}

    public RacewayAmpacityPane(){
        VBox page=new VBox(13);page.setPadding(new Insets(2));
        Label title=new Label("Raceway Fill + Ampacity Derating");title.setStyle("-fx-font-size:22px;-fx-font-weight:bold;-fx-text-fill:#0f172a;");
        Label sub=new Label("For CEC Rule 4-006, use the selected equipment TERMINATION-temperature column for base ampacity AND applicable corrections. A 90°C-insulated wire on 60°C terminals does not use the 90°C ampacity column.");sub.setWrapText(true);sub.setStyle("-fx-text-fill:#64748b;");page.getChildren().addAll(title,sub);

        ComboBox<String> raceType=combo(RACEWAY.keySet());raceType.setValue("EMT");ComboBox<String> raceSize=combo(List.of());TextField raceArea=field("");
        ChoiceBox<Integer> insulation=choice(90,60,75,90),termination=choice(60,60,75,90),ambient=choice(30,30,35,40,45,50,55,60,65,70,75,80);
        Runnable syncRace=()->{LinkedHashMap<String,Double> map=RACEWAY.get(raceType.getValue());String old=raceSize.getValue();raceSize.getItems().setAll(map.keySet());raceSize.setValue(old!=null&&map.containsKey(old)?old:map.keySet().iterator().next());raceArea.setText(fmt(map.get(raceSize.getValue())));};raceType.setOnAction(e->syncRace.run());raceSize.setOnAction(e->{Double a=RACEWAY.get(raceType.getValue()).get(raceSize.getValue());if(a!=null)raceArea.setText(fmt(a));});syncRace.run();

        VBox setup=card("1. Raceway and thermal conditions","Copper raceway/cable starter presets are only examples. Select a marked termination rating or the applicable Rule 4-006 unmarked-equipment default; verify the actual terminal, raceway dimensions, conductor material, and installation method.");setup.getChildren().addAll(row("Raceway type",raceType),row("Trade size",raceSize),row("100% internal area (mm²)",raceArea),row("Insulation rating (°C)",insulation),row("Verified equipment termination column (°C)",termination),row("Ambient temperature (°C)",ambient));

        VBox rowBox=new VBox(7);List<Row> rows=new ArrayList<>();Runnable add=()->{Row x=new Row(rows,rowBox,termination);rows.add(x);rowBox.getChildren().add(x.node);};add.run();add.run();rows.get(0).size.setValue("12 AWG");rows.get(0).physical.setText("3");rows.get(0).ccc.setText("3");rows.get(0).required.setText("20");rows.get(0).sync(termination.getValue());rows.get(1).size.setValue("10 AWG");rows.get(1).physical.setText("1");rows.get(1).ccc.setText("0");rows.get(1).required.setText("0");rows.get(1).sync(termination.getValue());
        termination.setOnAction(e->rows.forEach(x->x.sync(termination.getValue())));
        Button addBtn=secondary("+ Add conductor group");addBtn.setOnAction(e->add.run());Button resetRows=secondary("Reset groups");resetRows.setOnAction(e->{rows.clear();rowBox.getChildren().clear();add.run();});
        VBox conductors=card("2. Conductor groups","Set CCC to 0 only when the conductor is not current-carrying under the applicable rule. Base ampacity must be from the selected termination column of the appropriate Code table. Preset copper Table 2 values and areas are illustrative and must be checked.");conductors.getChildren().addAll(rowBox,new HBox(8,addBtn,resetRows));

        TextArea out=new TextArea("Enter the raceway installation, then calculate.");out.setEditable(false);out.setWrapText(true);out.setPrefRowCount(20);out.setStyle("-fx-font-family:Consolas;-fx-font-size:12px;-fx-control-inner-background:#0f172a;-fx-text-fill:#e2e8f0;");Label status=new Label();status.setWrapText(true);status.setStyle("-fx-text-fill:#475569;-fx-font-weight:bold;");Button calc=primary("Calculate fill + derating");
        calc.setOnAction(e->{try{double internal=positive(raceArea,"Raceway area");int physicalTotal=0,cccTotal=0;double used=0;for(Row x:rows){int n=nonNeg(x.physical,"Physical quantity"),c=nonNeg(x.ccc,"CCC quantity");if(c>n)throw new IllegalArgumentException("Current-carrying quantity cannot exceed physical quantity in a conductor group.");if(n==0)continue;physicalTotal+=n;cccTotal+=c;used+=n*positive(x.area,"Conductor area");}if(physicalTotal<1)throw new IllegalArgumentException("Add at least one physical conductor.");if(physicalTotal>200)throw new IllegalArgumentException("The entered physical conductor count exceeds the 200-conductor conduit/tubing run limit used by this CEC worksheet.");if(insulation.getValue()<termination.getValue())throw new IllegalArgumentException("Wire insulation rating cannot be lower than equipment termination temperature.");
        double fillLimit=physicalTotal==1?53:physicalTotal==2?31:40,allowedArea=internal*fillLimit/100,fill=used/internal*100,tf=ambientFactor(ambient.getValue(),termination.getValue()),gf=groupFactor(cccTotal);boolean fillPass=used<=allowedArea+1e-9;StringBuilder detail=new StringBuilder();boolean ampPass=true;for(Row x:rows){int n=nonNeg(x.physical,"Physical quantity"),c=nonNeg(x.ccc,"CCC quantity");if(n==0)continue;double base=positive(x.base,"Termination-column base ampacity"),term=terminationAmpacity(x.size.getValue(),termination.getValue(),base),adjusted=Math.min(base,term)*tf*gf,req=num(x.required);if(!Double.isFinite(req)||req<0)throw new IllegalArgumentException("Required current must be finite and nonnegative.");boolean ok=c==0||req<=0||adjusted+1e-9>=req;if(!ok)ampPass=false;detail.append(String.format(Locale.CANADA,"  %d physical / %d CCC × %-10s | area %.2f mm² ea | base %.1f A | adjusted %.1f A%s%n",n,c,x.size.getValue(),positive(x.area,"Area"),base,adjusted,req>0?String.format(Locale.CANADA," | required %.1f A → %s",req,ok?"PASS":"FAIL"):""));}String minimum=minimumRaceway(raceType.getValue(),used,fillLimit);String text=String.format(Locale.CANADA,"RACEWAY + DERATING RESULT%n%nRaceway: %s · %s%nPhysical conductors: %d%nCurrent-carrying conductors: %d%nOccupied area: %.2f mm²%nFill limit: %.0f%%%nAllowed occupied area: %.2f mm²%nActual fill: %.2f%%%nMinimum listed %s size: %s%nFILL STATUS: %s%n%nAmbient factor (%d°C / %d°C TERMINATION column): %.2f%nGrouping factor (%d CCC): %.2f%nCombined thermal multiplier: %.4f%nAMPACITY STATUS: %s%n%nCONDUCTOR GROUPS%n%s%nTRACEABILITY / REMINDERS%n• Section 12 / Table 9-series workflow: physical raceway fill.%n• Rule 4-004 and Tables 5A/5C: conductor ampacity correction/adjustment.%n• Rule 4-006: use the TERMINATION column ampacity AND corresponding correction factors.%n• Count current-carrying conductors under the actual circuit/load rules; do not assume every neutral counts or never counts.%n• Bonding conductors occupy raceway space even though they are not current-carrying load conductors.%n• Verify conductor construction/diameter, adopted provincial amendments, equipment markings and all applicable exceptions.",raceType.getValue(),raceSize.getValue(),physicalTotal,cccTotal,used,fillLimit,allowedArea,fill,raceType.getValue(),minimum,fillPass?"PASS (entered fill data)":"FAIL",ambient.getValue(),termination.getValue(),tf,cccTotal,gf,tf*gf,ampPass?"MEETS ENTERED LOADS ARITHMETICALLY (NOT CODE-VERIFIED)":"FAIL FOR ONE OR MORE ENTERED LOADS",detail);out.setText(text);boolean both=fillPass&&ampPass;status.setText(both?"Arithmetic checks fit entered limits; NOT field or code verified.":"Review result — one or more entered fill/ampacity checks fail.");}catch(Exception ex){out.setText(ex.getMessage()==null?ex.toString():ex.getMessage());status.setText("Check inputs");}});
        VBox results=card("3. Coordinated result","One result shows both the physical raceway occupancy and thermal ampacity impact.");results.getChildren().addAll(calc,status,out);page.getChildren().addAll(setup,conductors,results);ScrollPane s=new ScrollPane(page);s.setFitToWidth(true);s.setStyle("-fx-background:transparent;-fx-background-color:transparent;");setCenter(s);
    }

    private final class Row {final HBox node=new HBox(6);final ComboBox<String> size=combo(CU.keySet());final TextField physical=field("1"),ccc=field("1"),area=field(""),base=field(""),required=field("0");Row(List<Row> list,VBox parent,ChoiceBox<Integer> termination){size.setValue("12 AWG");size.setPrefWidth(105);physical.setPrefWidth(55);ccc.setPrefWidth(55);area.setPrefWidth(80);base.setPrefWidth(75);required.setPrefWidth(75);size.setOnAction(e->sync(termination.getValue()));Button x=secondary("×");x.setOnAction(e->{parent.getChildren().remove(node);list.remove(this);});node.setAlignment(Pos.CENTER_LEFT);node.getChildren().addAll(size,new Label("Qty"),physical,new Label("CCC"),ccc,new Label("mm²"),area,new Label("Base A"),base,new Label("Req A"),required,x);sync(termination.getValue());}void sync(int temp){Preset p=CU.get(size.getValue());if(p==null)return;area.setText(fmt(p.area()));base.setText(fmt(temp==60?p.a60():temp==75?p.a75():p.a90()));}}
    private static double terminationAmpacity(String size,int temp,double fallback){Preset p=CU.get(size);if(p==null)return fallback;return temp==60?p.a60():temp==75?p.a75():p.a90();}
    private static double ambientFactor(int amb,int rating){if(amb<=30)return 1;Map<Integer,double[]> m=Map.of(35,new double[]{.91,.94,.96},40,new double[]{.82,.88,.91},45,new double[]{.71,.82,.87},50,new double[]{.58,.75,.82},55,new double[]{.41,.67,.76},60,new double[]{Double.NaN,.58,.71},65,new double[]{Double.NaN,.47,.65},70,new double[]{Double.NaN,.33,.58},75,new double[]{Double.NaN,Double.NaN,.50},80,new double[]{Double.NaN,Double.NaN,.41});double[] a=m.get(amb);if(a==null)throw new IllegalArgumentException("Unsupported ambient temperature.");double f=a[rating==60?0:rating==75?1:2];if(!Double.isFinite(f))throw new IllegalArgumentException("Selected insulation rating has no usable correction factor at that ambient temperature.");return f;}
    private static double groupFactor(int n){if(n<=3)return 1;if(n<=6)return .8;if(n<=24)return .7;if(n<=42)return .6;return .5;}
    private static String minimumRaceway(String type,double used,double limit){for(Map.Entry<String,Double> e:RACEWAY.get(type).entrySet())if(used<=e.getValue()*limit/100)return e.getKey();return "larger than listed presets";}
    private VBox card(String title,String desc){VBox b=new VBox(10);b.setStyle(CARD);Label h=new Label(title);h.setStyle("-fx-font-size:17px;-fx-font-weight:bold;-fx-text-fill:#0f172a;");Label d=new Label(desc);d.setWrapText(true);d.setStyle("-fx-text-fill:#64748b;");b.getChildren().addAll(h,d);return b;}
    private HBox row(String l,Control c){Label x=new Label(l);x.setMinWidth(250);x.setStyle("-fx-font-weight:bold;-fx-text-fill:#334155;");HBox h=new HBox(10,x,c);h.setAlignment(Pos.CENTER_LEFT);HBox.setHgrow(c,Priority.ALWAYS);c.setMaxWidth(Double.MAX_VALUE);return h;}
    private static TextField field(String v){TextField f=new TextField(v);f.setStyle(INPUT);return f;}
    private static <T> ComboBox<T> combo(Collection<T> v){ComboBox<T> c=new ComboBox<>();c.getItems().addAll(v);return c;}
    @SafeVarargs private final <T> ChoiceBox<T> choice(T selected,T... vals){ChoiceBox<T> c=new ChoiceBox<>();c.getItems().addAll(vals);c.setValue(selected);return c;}
    private Button primary(String s){Button b=new Button(s);b.setStyle(PRIMARY);return b;}
    private Button secondary(String s){Button b=new Button(s);b.setStyle(SECONDARY);return b;}
    private static double positive(TextField f,String n){try{double v=Double.parseDouble(f.getText().trim());if(!Double.isFinite(v)||v<=0)throw new Exception();return v;}catch(Exception e){throw new IllegalArgumentException(n+" must be greater than zero.");}}
    private static int nonNeg(TextField f,String n){try{int v=Integer.parseInt(f.getText().trim());if(v<0)throw new Exception();return v;}catch(Exception e){throw new IllegalArgumentException(n+" must be zero or a positive whole number.");}}
    private static double num(TextField f){try{double value=Double.parseDouble(f.getText().trim());if(!Double.isFinite(value))throw new NumberFormatException();return value;}catch(Exception e){throw new IllegalArgumentException("Enter a valid finite current value; use zero when no load is present.");}}
    private static String fmt(double d){return Math.abs(d-Math.rint(d))<1e-9?String.format(Locale.CANADA,"%.0f",d):String.format(Locale.CANADA,"%.2f",d);}
}
